<script setup lang="ts">
// SPDX-License-Identifier: AGPL-3.0-only
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import {useWorkspace} from '../state/workspace'
import {useRouter} from '../state/navigation'
import {useLocale} from '../state/locale'
import {statusLabel} from '../domain/status'
import IntakeStatus from './IntakeStatus.vue'
const store=useWorkspace(),router=useRouter(),{t}=useLocale(),queue=ref<any[]>([]),nextCursor=ref<string|null>(null),enabled=ref(false),busy=ref(false),error=ref('')
const checking=computed(()=>!!store.intakeHealth.value?.manualCheck)
let lastRefresh=0,alive=true,timer:ReturnType<typeof setInterval>|undefined
async function load(more=false){if(busy.value)return;busy.value=true;try{const r=await store.request('intake',more?{cursor:nextCursor.value}:{});if(!alive)return;queue.value=more?[...queue.value,...r.queue.filter((row:any)=>!queue.value.some(old=>old.id===row.id))]:r.queue;nextCursor.value=r.nextCursor??null;enabled.value=r.configuration.enabled;store.intakeQueue.value=r.queue;store.intakeHealth.value=r.health;store.intakeSessionAttached.value=r.sessionAttached===true;error.value=''}catch(e){if(alive)error.value=e instanceof Error?e.message:'Could not load history'}finally{busy.value=false}}
async function run(operation:string,body:Record<string,unknown>={}){if(busy.value)return;busy.value=true;error.value='';try{await store.request(operation,body)}catch(e){error.value=e instanceof Error?e.message:'Processing held';return}finally{busy.value=false}await load()}
async function open(item:any){try{await store.openJob(item.job);await router.push({path:item.decision==='done'?'/document-workflow/documents':'/document-workflow/inbox',query:{job:item.job}})}catch(e){error.value=e instanceof Error?e.message:'Could not open document'}}
onMounted(()=>{void load();timer=setInterval(()=>{if(!nextCursor.value&&!busy.value&&(checking.value||Date.now()-lastRefresh>=10000)){lastRefresh=Date.now();void load()}},1000)})
onBeforeUnmount(()=>{alive=false;clearInterval(timer)})
</script>
<template><section><div class="history-toolbar"><IntakeStatus :enabled="enabled" :attached="store.intakeSessionAttached.value" :health="store.intakeHealth.value" /><button class="button" :disabled="busy||!enabled||checking" @click="run('intake-scan')">{{ t(checking?'Checking…':'Check now') }}</button></div><p v-if="error" class="error" role="alert">{{ t(error) }}</p><section class="panel document-list"><table v-if="queue.length"><thead><tr><th>{{ t('Document') }}</th><th>{{ t('Status') }}</th><th>{{ t('Attempts') }}</th><th></th></tr></thead><tbody><tr v-for="item in queue" :key="item.id"><td><button v-if="item.job&&!['duplicate','trashed'].includes(item.state)" class="document-link" @click="open(item)">{{ item.path.split('/').pop() }}</button><span v-else>{{ item.path.split('/').pop() }}</span><details v-if="item.automation?.detail||item.detail"><summary>{{ t('Details') }}</summary>{{ t(item.automation?.detail||item.detail) }}</details></td><td>{{ t(item.automation?.state==='held'?'Needs attention':item.automation?.state==='done'?'Processed':statusLabel(item.state==='prepared'&&item.decision?item.decision:item.state)) }}</td><td>{{ item.attempts }}</td><td><button v-if="item.state==='duplicate'" class="button" :disabled="busy" @click="run(item.trash?'duplicate-verify':'duplicate-trash',{id:item.id})">{{ t(item.trash?'Verify Trash outcome':'Move to OpenCloud Trash') }}</button><button v-if="['duplicate','trashed'].includes(item.state)&&item.job" class="button subtle" :disabled="busy" @click="open(item)">{{ t('Open original') }}</button><button v-if="item.state==='failed'" class="button" :disabled="busy" @click="run('intake-retry',{id:item.id})">{{ t('Retry') }}</button><button v-if="item.state==='prepared'&&!item.decision&&item.automation?.state!=='done'" class="button" :disabled="busy" @click="run('automation-run',{id:item.job,retry:true})">{{ t('Run automatic rules') }}</button></td></tr></tbody></table><p v-else class="empty-state">{{ t('No processing history') }}</p><button v-if="nextCursor" class="button" :disabled="busy" @click="load(true)">{{ t('Load more') }}</button></section></section></template>
<style scoped>.history-toolbar{display:flex;align-items:center;gap:12px}.history-toolbar .intake-health{flex:1}.document-list td{vertical-align:middle}details{font-size:12px;max-width:400px;margin-top:8px}summary{cursor:pointer;color:var(--muted)}</style>
